import csv, json, collections, datetime, ast
P='/app/dataset/'
def read(n):
 with open(P+n, newline='', encoding='utf-8-sig') as f:return list(csv.DictReader(f))
emps=read('employees.csv'); tasks=read('tasks.csv'); ts=read('timesheet.csv')
print('employee IDs',len(emps),len(set(x['PESEL'] for x in emps)))
print('task IDs',len(tasks),len(set(x['task_id'] for x in tasks)))
print('timesheet IDs',len(ts),len(set(x['id'] for x in ts)))
print('dates',min(x['date'] for x in ts),max(x['date'] for x in ts))
dates=[datetime.date.fromisoformat(x['date']) for x in ts]
first=min(dates); print('earliest',first, first.strftime('%A'))
print('weekdays',collections.Counter(x.strftime('%A') for x in dates))
print('months',collections.Counter(x.strftime('%Y-%m') for x in dates))
empids={x['PESEL'] for x in emps}; taskids={x['task_id'] for x in tasks}
print('unknown emp',collections.Counter(x['employee_id'] for x in ts if x['employee_id'] not in empids))
print('unknown task IDs:')
c=collections.Counter()
for x in ts:
 try: t=ast.literal_eval(x['performed_tasks'])
 except Exception as e: print('parse err',x['id'],repr(x['performed_tasks']));continue
 c.update(str(i) for i in t if str(i) not in taskids)
print(c)
print('task pay categories',collections.Counter(x['pay_per_completion'] for x in tasks))
print('employees:')
for e in emps: print(e['PESEL'],e['hourly_rate'],e['hire_date'])
print('potential invalid records')
for x in ts:
 vals=[]
 try: d=datetime.date.fromisoformat(x['date'])
 except Exception: vals.append('bad date'); d=None
 try: h=float(x['hours_worked'])
 except: vals.append('bad hours');h=None
 try: t=ast.literal_eval(x['performed_tasks'])
 except Exception: vals.append('bad tasks');t=[]
 if x['employee_id'] not in empids: vals.append('unknown emp')
 if d and x['employee_id'] in {e['PESEL'] for e in emps}:
  e=next(e for e in emps if e['PESEL']==x['employee_id'])
  if d<datetime.date.fromisoformat(e['hire_date']): vals.append('prehire')
 if h is not None and (h<=0 or h>24): vals.append('hours range')
 if vals: print(x['id'],vals,x)
