const r = await tools.exec_command({cmd:"python - <<'PY'
import csv, collections, ast, datetime, json
P='/app/dataset/'
def read(n):
 with open(P+n, newline='', encoding='utf-8-sig') as f:return list(csv.DictReader(f))
emps=read('employees.csv'); tasks=read('tasks.csv'); ts=read('timesheet.csv')
dates=[]
for x in ts:
 try:d=datetime.date.fromisoformat(x['date'])
 except Exception as ex: print('bad date',x['id'],x['date'],x);continue
 dates.append(d)
print('valid dates',min(dates),max(dates),min(dates).strftime('%A'))
print('month date ranges and weekday counts')
for m in sorted(set(d.strftime('%Y-%m') for d in dates)):
 ds=[d for d in dates if d.strftime('%Y-%m')==m]
 print(m,min(ds),max(ds),len(ds),collections.Counter(d.strftime('%A') for d in ds))
print('bad/all malformed fields')
emp={e['PESEL']:e for e in emps};taskids={t['task_id'] for t in tasks}
for x in ts:
 issues=[]
 try: d=datetime.date.fromisoformat(x['date'])
 except: d=None; issues.append('date')
 try: h=float(x['hours_worked'])
 except: h=None;issues.append('hoursparse')
 try: t=ast.literal_eval(x['performed_tasks'])
 except: t=[];issues.append('taskparse')
 try: sal=float(x['salary_amount'])
 except: sal=None;issues.append('salaryparse')
 try: bon=float(x['bonus'])
 except: bon=None;issues.append('bonusparse')
 if x['employee_id'] not in emp: issues.append('unknown employee')
 if any(str(tid) not in taskids for tid in t): issues.append('unknown task')
 if h is not None and not (0 <= h <= 24):issues.append('hours range')
 if d and x['employee_id'] in emp and d<datetime.date.fromisoformat(emp[x['employee_id']]['hire_date']): issues.append('prehire')
 if issues: print(x['id'],','.join(issues),x)
print('months raw counter',collections.Counter(x['date'][:7] for x in ts))
print('Dates March-Apr-Jun')
for month in ['2025-03','2025-04','2025-05','2025-06']:
 c=collections.Counter(x['date'][8:] for x in ts if x['date'].startswith(month))
 print(month, sorted(c.items(),key=lambda z:int(z[0])))
