from __future__ import annotations

import calendar
import csv
import json
import re
from bisect import bisect_right
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


DATA_DIR = Path("/app/dataset")


def _read_csv(filename: str) -> list[dict[str, str]]:
    with (DATA_DIR / filename).open("r", newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))


def _parse_date(value: str) -> date | None:
    """Parse a date, repairing an overlong day to that month's last day."""
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        match = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", value or "")
        if not match:
            return None
        year, month, day = map(int, match.groups())
        if not 1 <= month <= 12 or day < 1:
            return None
        last_day = calendar.monthrange(year, month)[1]
        if day > last_day and day <= 31:
            return date(year, month, last_day)
        return None


def _parse_task_ids(value: str) -> list[str] | None:
    """Accept a comma-separated ID list even if its outer brackets are damaged."""
    cleaned = re.sub(r"[\[\]\s]", "", value or "")
    if not cleaned:
        return []
    parts = cleaned.split(",")
    if all(re.fullmatch(r"\d+", part) for part in parts):
        return parts
    return None


def _period_starts(first: date, last: date) -> list[date]:
    """Return each month's first occurrence of the earliest record's weekday."""
    starts: list[date] = []
    year, month = first.year, first.month
    while (year, month) <= (last.year, last.month):
        month_first = date(year, month, 1)
        offset = (first.weekday() - month_first.weekday()) % 7
        starts.append(month_first + timedelta(days=offset))
        if month == 12:
            year, month = year + 1, 1
        else:
            month += 1
    return starts


def answer() -> dict[str, list[int]]:
    employees: dict[str, Decimal] = {}
    for row in _read_csv("employees.csv"):
        try:
            rate = Decimal(row["hourly_rate"])
            if rate >= 0:
                employees[row["PESEL"]] = rate
        except (InvalidOperation, KeyError):
            continue

    task_prices: dict[str, Decimal] = {}
    for row in _read_csv("tasks.csv"):
        try:
            price = Decimal(row["pay_per_completion"])
            if price >= 0:
                task_prices[row["task_id"]] = price
        except (InvalidOperation, KeyError):
            continue

    timesheets = _read_csv("timesheet.csv")
    parsed_dates = [d for row in timesheets if (d := _parse_date(row.get("date", ""))) is not None]
    if not parsed_dates:
        return {pesel: [] for pesel in employees}

    first, last = min(parsed_dates), max(parsed_dates)
    starts = _period_starts(first, last)
    start_months = [(d.year, d.month) for d in starts]
    monthly_totals: dict[tuple[str, tuple[int, int]], Decimal] = defaultdict(Decimal)

    for row in timesheets:
        pesel = row.get("employee_id", "")
        if pesel not in employees:
            # No rate or reliable employee identity is available for this row.
            continue

        work_date = _parse_date(row.get("date", ""))
        if work_date is None:
            continue
        period_index = bisect_right(starts, work_date) - 1
        if period_index < 0:
            continue
        period_month = start_months[period_index]

        try:
            hours = Decimal(row["hours_worked"])
            if not hours.is_finite() or hours < 0 or hours > 24:
                continue
        except (InvalidOperation, KeyError):
            continue

        # Use the task catalog as the source of bonus values. Unknown task IDs
        # cannot be priced, so their bonus is omitted while valid tasks and
        # recorded hours on the same row are still counted.
        task_ids = _parse_task_ids(row.get("performed_tasks", ""))
        bonus = Decimal(0)
        if task_ids is not None:
            bonus = sum((task_prices[task_id] for task_id in task_ids if task_id in task_prices), Decimal(0))

        monthly_totals[(pesel, period_month)] += hours * employees[pesel] + bonus

    ordered_months = start_months
    result: dict[str, list[int]] = {}
    for pesel in employees:
        result[pesel] = [
            int(monthly_totals[(pesel, month)].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in ordered_months
        ]
    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, ensure_ascii=False)

